def evaluate(current_reputation, observation, my_history, round_num):
    # Compute our own cooperation rate from personal history
    total_actions = len(my_history)
    if total_actions > 0:
        coop_count = sum(1 for a in my_history if a == 'cooperate')
        self_coop_rate = coop_count / total_actions
    else:
        self_coop_rate = 0.5  # neutral initial assumption

    # Dynamic update based on our own behavior
    action = observation['action']
    if action == 'cooperate':
        base_update = 0.2 * (1 + 0.3 * self_coop_rate)  # reward more when we cooperate often
    else:
        base_update = -0.35 * (1 - 0.4 * self_coop_rate)  # punish less harshly when we are cooperative

    # Exponential smoothing with slightly different weighting
    new_rep = 0.85 * current_reputation + base_update
    return max(-1.0, min(1.0, new_rep))


