def decide(recipient_reputation, round_num, my_history):
    # Compute own cooperation rate (indirect, not partner-specific)
    if len(my_history) == 0:
        own_coop_rate = 0.5
    else:
        coop_count = sum(1 for move in my_history if move['action'] == 'cooperate')
        own_coop_rate = coop_count / len(my_history)
    # Threshold increases with own cooperation (more selective) and with round number (less trusting over time)
    threshold = 0.2 + 0.2 * own_coop_rate + 0.1 * (round_num / 10)
    return recipient_reputation > threshold
